function getLerpColor(pal, f) {
	const c1I = ~~(pal.length * f);
	const c2I = (c1I + 1) % pal.length;
	const cf = (f % (1/pal.length)) / (1/pal.length); // map(f, c1I/pal.length, (c1I+1)/pal.length, 0, 1);
	// console.log(`f ${f}, cf ${cf}`)
	return lerpColor(color(pal[c1I]), color(pal[c2I]), cf);
}

var palettes = [
	["steelblue", "white", "purple"],
