/*
	Spiral Galaxy #genuary1 #genuary #genuary2501
	Vertical or horizontal lines only
	https://openprocessing.org/sketch/2498632
	#generativeart #creativecoding #p5js
*/

var palette;
var len;

var spiralParams = {N: 4, A: 1, B: 0.4};

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("spiral galaxy with stars made of short slightly rotated horiziontal and vertical lines");
	frameRate(15);
	palette = random(palettes);
	spiralParams = {N: ~~random(4, 16), A: random(1, 3), B: random(0.2, 2)};
	len = ~~(max(width, height) * 0.03);
	background(2, 2, 12);
}

function draw() {
	drawCross(width/2, height/2, len);
	drawMsg("Spiral Galaxy (epi) #genuary2501")
}

function drawCross(x, y, l) {
	let n = noise(x/123, y/231, frameCount/42);
	const n2 = noise(12+x/4321, 23 + y/5432, frameCount/1234);
	strokeWeight((n)*3);
	const clr = getLerpColor(palette, fract(n*10));

	const pos = calcSpiralArmPos(50);
	if (!pos.x || !pos.y) return;
	l = pow(dist(0, 0, pos.x, pos.y), 0.35)

	push();
	const fx = 1; // Math.sign(random()-0.5);
	const fy = Math.sign(random()-0.5); // not used, can be taken for 4 arms in translate() by pos.y*fy
	// translate(x + pos.x, y + pos.y)
	translate(randomGaussian(x + pos.x * fx, l), randomGaussian(y + pos.y * fy, l));
	rotate((n2-0.5)*HALF_PI);
	clr.setAlpha(128);
	stroke(clr)
	line(-l*n, 0, l*n, 0);
	line(0, -l*n, 0, l*n);

	strokeWeight(1);
	for (let i = 0; i < 6; i++) {		
		clr.setAlpha(48 - i * 7);
		stroke(clr);
		l *= random(1.7, 3);
		line(-l*n, 0, l*n, 0);
		line(0, -l*n, 0, l*n);
	}
	pop();
}

// https://arxiv.org/pdf/0908.0892
function calcSpiralArmPos(scl = 1) {
	const N = spiralParams.N; // 12;
	const A = spiralParams.A; // 1.7;
	const B = spiralParams.B; // 0.24;
	const phi = random(N * TWO_PI);
	const r = A / (log(B * tan(phi/(2*N))))

	const x = cos(phi) * r * scl;
	const y = sin(phi) * r * scl;

	return {x, y};
}

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function drawMsg(msg) {
	push();
	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)
	pop();
}
